"use client";

import { type FormEvent, useActionState, useState } from "react";
import { type ContactErrors, type ContactState, readContactForm, validateContact } from "@/lib/contact";
import { sendContact } from "./actions";

const initialState: ContactState = {
  values: { name: "", email: "", message: "" },
  errors: {},
  success: null,
};

export function ContactForm() {
  const [state, formAction, pending] = useActionState(sendContact, initialState);
  const [clientErrors, setClientErrors] = useState<ContactErrors | null>(null);
  const errors = clientErrors ?? state.errors;
  const success = clientErrors ? null : state.success;

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    const found = validateContact(readContactForm(new FormData(event.currentTarget)));
    if (Object.keys(found).length > 0) {
      event.preventDefault();
      setClientErrors(found);
    } else {
      setClientErrors(null);
    }
  }

  return (
    <>
      {success ? (
        <p role="status" className="success">
          {success}
        </p>
      ) : null}
      <form action={formAction} onSubmit={handleSubmit} noValidate className="contact-form">
        <div className="field">
          <label htmlFor="contact-name">Name</label>
          <input
            id="contact-name"
            name="name"
            type="text"
            defaultValue={state.values.name}
            aria-invalid={errors.name ? true : undefined}
            aria-describedby={errors.name ? "contact-name-error" : undefined}
          />
          {errors.name ? (
            <p id="contact-name-error" className="error">
              {errors.name}
            </p>
          ) : null}
        </div>
        <div className="field">
          <label htmlFor="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            defaultValue={state.values.email}
            aria-invalid={errors.email ? true : undefined}
            aria-describedby={errors.email ? "contact-email-error" : undefined}
          />
          {errors.email ? (
            <p id="contact-email-error" className="error">
              {errors.email}
            </p>
          ) : null}
        </div>
        <div className="field">
          <label htmlFor="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            rows={5}
            defaultValue={state.values.message}
            aria-invalid={errors.message ? true : undefined}
            aria-describedby={errors.message ? "contact-message-error" : undefined}
          />
          {errors.message ? (
            <p id="contact-message-error" className="error">
              {errors.message}
            </p>
          ) : null}
        </div>
        <button type="submit" disabled={pending}>
          Send
        </button>
      </form>
    </>
  );
}
