import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { FavoriteButton } from "@/components/favorite-button";
import { getBook, getBooks } from "@/lib/books";

export async function generateStaticParams() {
  const books = await getBooks();
  return books.map((book) => ({ slug: book.slug }));
}

export async function generateMetadata({ params }: PageProps<"/books/[slug]">): Promise<Metadata> {
  const { slug } = await params;
  const book = await getBook(slug);
  return { title: book ? `${book.title} | Bookshelf` : "Not found | Bookshelf" };
}

export default async function BookPage({ params }: PageProps<"/books/[slug]">) {
  const { slug } = await params;
  const book = await getBook(slug);
  if (!book) notFound();

  return (
    <article>
      <h1>{book.title}</h1>
      <p>by {book.author}</p>
      <p>Published in {book.year}</p>
      <p>Rating: {book.rating}/5</p>
      <ul aria-label="Tags" className="tags">
        {book.tags.map((tag) => (
          <li key={tag}>
            <Link href="/books">{tag}</Link>
          </li>
        ))}
      </ul>
      <div className="book-body" dangerouslySetInnerHTML={{ __html: book.html }} />
      <FavoriteButton slug={book.slug} />
    </article>
  );
}
