"use client";

import Link from "next/link";
import { useSelectedLayoutSegment } from "next/navigation";

const LINKS = [
  { href: "/books", segment: "books", label: "Books" },
  { href: "/about", segment: "about", label: "About" },
  { href: "/contact", segment: "contact", label: "Contact" },
] as const;

/**
 * Reads the active top-level route segment rather than the URL, so a 404 page
 * (including an unknown book slug rewritten by the proxy) marks no section.
 */
export function MainNav() {
  const segment = useSelectedLayoutSegment();
  return (
    <nav aria-label="Main">
      <ul>
        {LINKS.map((link) => (
          <li key={link.href}>
            <Link href={link.href} aria-current={segment === link.segment ? "page" : undefined}>
              {link.label}
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
}
