import { existsSync } from "node:fs";
import path from "node:path";
import { type NextRequest, NextResponse } from "next/server";

const BOOKS_DIR = path.join(process.cwd(), "content", "books");

/**
 * Unknown book slugs are rewritten to the not-found route before rendering
 * starts, so they answer with a 404 status instead of a streamed fallback.
 */
export function proxy(request: NextRequest) {
  const raw = request.nextUrl.pathname.slice("/books/".length).replace(/\/$/, "");
  let slug: string;
  try {
    slug = decodeURIComponent(raw);
  } catch {
    slug = "";
  }
  const isBook =
    /^[A-Za-z0-9._-]+$/.test(slug) &&
    !slug.startsWith(".") &&
    existsSync(path.join(BOOKS_DIR, `${slug}.md`));
  if (isBook) return NextResponse.next();
  return NextResponse.rewrite(new URL("/_not-found", request.url));
}

export const config = {
  matcher: "/books/:slug",
};
EOF
